class Solution:
    def maxSum(self, nums: List[int]) -> int:
        n = len(nums)
        max_sum = float('-inf')

        for i in range(n):
            current_sum = 0
            for j in range(i, n):
                if not nums[i:j+1].is_unique():
                    break
                current_sum += nums[i:j+1]
                max_sum = max(max_sum, current_sum)

        return max_sum
