        M = int(next(iterator))

        S = []
        for _ in range(N):
            S.append(next(iterator))

        T = []
        for _ in range(M):
            T.append(next(iterator))

    except StopIteration:
        return

    # Iterate through all possible top-left positions (a, b)
    # The subgrid starts at row a-1 and column b-1 in 0-indexed notation
    # Constraints: 1 <= a, b <= N - M + 1
    # In 0-indexed terms, start_row goes from 0 to N - M, start_col goes from 0 to N - M

    found = False
    result = None

    for start_row in range(N - M + 1):
        for start_col in range(N - M + 1):
            # Check if the subgrid starting at (start_row, start_col) matches T
            match = True
            for i in range(M):
                for j in range(M):
                    if S[start_row + i][start_col + j] != T[i][j]:
                        match = False
                        break
                if not match:
                    break

            if match:
                # Found the match. Since the problem guarantees a unique solution,
                # we can stop here.
                result = (start_row + 1, start_col + 1)
                found = True
                break
        if found:
            break

    if found:
        print(result)
    else:
        # Should not be reached given the problem statement
        pass

